def q597(chunks):
    import codecs
    import itertools

    decoder = codecs.getincrementaldecoder("utf-8")()
    line = ""
    pending_cr = False
    data = []
    events = []

    def finish_line(text):
        if text == "":
            if data:
                events.append("\n".join(data))
                data.clear()
        elif not text.startswith(":"):
            field, separator, value = text.partition(":")
            if value.startswith(" "):
                value = value[1:]
            if field == "data":
                data.append(value if separator else "")

    for chunk in itertools.chain(chunks, [None]):
        text = decoder.decode(
            chunk if chunk is not None else b"", final=chunk is None
        )
        for character in text:
            if pending_cr:
                pending_cr = False
                if character == "\n":
                    continue
            if character in ("\r", "\n"):
                finish_line(line)
                line = ""
                pending_cr = character == "\r"
            else:
                line += character
    return events
